# Minimal, documented DBF/SHP reader for the single verified Polygon archive.
# No geography reconstruction from names: align records using the original P_02_ID key.
def read_polygons():
 z=zipfile.ZipFile(ROOT/'data/raw/uganda_2002_dissolve4.zip'); dbf=z.read(next(n for n in z.namelist() if n.endswith('.dbf'))); shp=z.read(next(n for n in z.namelist() if n.endswith('.shp')))
 count=struct.unpack('<I',dbf[4:8])[0];hlen,rlen=struct.unpack('<HH',dbf[8:12]);ids=[int(dbf[hlen+i*rlen+1:hlen+(i+1)*rlen].decode().strip()) for i in range(count)]
 pos=100;records=[]
 while pos<len(shp):
  size=struct.unpack('>i',shp[pos+4:pos+8])[0]*2;record=shp[pos+8:pos+8+size];pos+=8+size
  typ=struct.unpack('<i',record[:4])[0]
  if typ!=5: raise ValueError(f'Expected polygon type 5, found {typ}')
  nparts,npoints=struct.unpack('<ii',record[36:44]);starts=struct.unpack('<'+'i'*nparts,record[44:44+4*nparts]);points=np.frombuffer(record[44+4*nparts:],dtype='<f8',count=npoints*2).reshape(-1,2)
  records.append([points[a:b].copy() for a,b in zip(starts,list(starts[1:])+[npoints])])
 if len(ids)!=len(records) or len(set(ids))!=5378: raise ValueError('Geographic key mismatch')
 return dict(zip(ids,records))
polys=read_polygons();panel=pd.read_csv(O/'analysis_panel.csv.gz'); latest=panel[panel.year==2020].set_index('parish_id');paths=[];values=[]
for pid,parts in polys.items():
 value=latest.loc[pid,'presence'] if pid in latest.index and latest.loc[pid,'min_distance_01']<150 else np.nan
 for part in parts: paths.append(part);values.append(value)
fig,ax=plt.subplots(figsize=(7.2,5.0));coll=PolyCollection(paths,array=np.array(values),cmap='viridis',edgecolors='none');coll.cmap.set_bad('#e2e7e9');ax.add_collection(coll);ax.autoscale();ax.set_aspect('equal');ax.set_xlabel('Longitude');ax.set_ylabel('Latitude');ax.set_title('2020 refugee presence across study parishes');fig.colorbar(coll,ax=ax,label='Transformed presence, standardized over full panel',shrink=.76);fig.tight_layout();finish(fig,'presence_map')
